INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-fang','曹芳','wei','[]',NULL,NULL,231,1,NULL,'year',274,1,NULL,'year','["皇帝"]','曹叡养子，239年即位，至254年被废，在位期间先后由曹爽与司马懿辅政。249年高平陵之变后司马氏掌握魏国军政；司马师随后废曹芳为齐王，曹芳后来被降封为邵陵县公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹芳"}]','邵陵厉公',NULL,'齐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-huan','曹奂','wei','[]',NULL,NULL,246,1,NULL,'year',302,1,NULL,'year','["皇帝"]','曹操之孙、燕王曹宇之子，260年被司马昭拥立为帝，在位至266年。此时魏政由司马氏掌控；曹奂于咸熙二年禅位给司马炎，曹魏灭亡，随后受封陈留王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹奂"}]','元皇帝',NULL,'魏元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-mao','曹髦','wei','[]',NULL,NULL,241,1,NULL,'year',260,5,NULL,'month','["皇帝"]','曹丕之孙，254年由司马师拥立为帝，在位至260年。司马氏掌权期间，他曾试图亲自讨伐司马昭，兵败后在洛阳被成济所杀，是曹魏第四帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹髦"}]',NULL,NULL,'高贵乡公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yi','司马懿','wei','[]',NULL,NULL,179,1,NULL,'year',251,9,7,'day','["政治家","军事家"]','河内温县人，司马防之子，历仕曹操及魏文帝、明帝、齐王曹芳。曾与诸葛亮相持，238年平定公孙渊，239年与曹爽同受顾命，任太傅、封舞阳侯。249年发动高平陵之变，诛曹爽及其党羽，掌握魏廷军政；251年平定王凌后在洛阳去世，司马师继掌朝政。孙司马炎建立晋朝后追尊为宣皇帝，庙号高祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马懿"},{"label":"《晋书·宣帝纪》（维基文库）","url":"https://zh.wikisource.org/wiki/晉書/卷01"},{"label":"《晋书·宣帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷001"},{"label":"《三国志·三少帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷04"},{"label":"正始 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/正始_(曹魏)"},{"label":"嘉平 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/嘉平_(曹魏)"}]','宣文侯,宣王,宣皇帝','高祖',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-hao','孙皓','wu','[]',NULL,NULL,242,1,NULL,'year',284,1,NULL,'year','["皇帝"]','孙权之孙、孙和之子，264年孙休去世后被拥立为帝，在位至280年。初立时曾开仓赈贫、释放宫女，后渐趋专断，吴国又因交州动乱与对晋战事而局势恶化；280年晋军攻入建业，孙皓出降，孙吴灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙皓"}]',NULL,NULL,'吴末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-liang','孙亮','wu','[]',NULL,NULL,244,1,NULL,'year',260,6,NULL,'month','["皇帝"]','孙权少子，252年继位时年幼，由诸葛恪等辅政，在位至258年。诸葛恪被孙峻诛杀后，孙綝把持朝政并废孙亮为会稽王；孙亮后又被贬为侯官侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙亮"}]',NULL,NULL,'会稽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-xiu','孙休','wu','[]',NULL,NULL,235,1,NULL,'year',264,9,NULL,'month','["皇帝"]','孙权第六子，258年在孙綝废黜孙亮后被迎立，在位至264年。他与张布等合谋诛杀孙綝，随后改任相关官员、整顿政务；其子年幼，死后由侄孙皓继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙休"}]','景皇帝',NULL,'吴景帝','[]');
