INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('gaoping-tombs-incident','高平陵之变','politics','point','day',NULL,NULL,'《三国志·魏书·齐王纪》《晋书·宣帝纪》记正始十年正月甲午。正始纪年农历对照表正月朔为公历249-01-31己丑，甲午为初六，换算公历249-02-05；与司马懿掌权卡起点采用同一日期。',249,2,5,2989,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'曹芳赴高平陵谒陵时，司马懿控制洛阳及洛水浮桥，迫使曹爽交出兵权并夷其三族，曹魏政局转由司马氏掌握。',NULL,NULL);
